WITH SessionStats AS (SELECT session_id, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, COUNT(DISTINCT duration_sec) AS unique_pages FROM web_events GROUP BY session_id) SELECT sessions.country, sessions.started_at, SessionStats.avg_duration_sec, SessionStats.unique_pages FROM sessions INNER JOIN SessionStats ON sessions.id = SessionStats.session_id WHERE SessionStats.avg_duration_sec >= 39;
